name: CI

on:
  pull_request:
    types: [opened, synchronize, reopened]
  push:
    branches:
      - main
      - master
      - develop

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  # ============ 1. Flutter Analyze + Test + Coverage ============
  flutter:
    name: Flutter Analyze And Test
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Setup Flutter
        uses: subosito/flutter-action@v2
        with:
          channel: stable
          cache: true

      - name: Flutter pub get
        run: flutter pub get

      - name: Generate app review and dependency evidence
        run: |
          dart tools/generate_app.dart --app demo
          dart tools/generate_app.dart --app smartwear
          test -f apps/demo/generated/differentiation_evidence.md
          test -f apps/demo/generated/dependency_report.md
          test -f apps/smartwear/generated/differentiation_evidence.md
          test -f apps/smartwear/generated/dependency_report.md

      - name: Flutter analyze
        run: flutter analyze --fatal-infos --fatal-warnings

      - name: Flutter format check
        run: dart format --set-exit-if-changed lib/ test/

      - name: Flutter test with coverage
        run: flutter test --coverage

      - name: Upload Flutter coverage to Codecov
        uses: codecov/codecov-action@v5
        with:
          files: ./coverage/lcov.info
          flags: flutter
          fail_ci_if_error: false

  # ============ 2. Android Lint + Test + Build ============
  android:
    name: Android Lint & Test & Build
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Setup Java
        uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: "17"

      - name: Setup Flutter
        uses: subosito/flutter-action@v2
        with:
          channel: stable
          cache: true

      - name: Flutter pub get
        run: flutter pub get

      - name: Grant gradlew execute permission
        run: chmod +x android/gradlew

      - name: Run detekt (Kotlin static analysis)
        run: cd android && ./gradlew detekt

      - name: Run Android unit tests
        run: cd android && ./gradlew test

      - name: Build Android debug APK
        run: flutter build apk --debug

      - name: Upload APK artifact
        uses: actions/upload-artifact@v4
        with:
          name: android-debug-apk
          path: build/app/outputs/flutter-apk/app-debug.apk
          retention-days: 7

  # ============ 3. iOS Lint + Test + Build ============
  ios:
    name: iOS Lint & Test & Build
    runs-on: macos-latest
    steps:
      - uses: actions/checkout@v4

      - name: Setup Flutter
        uses: subosito/flutter-action@v2
        with:
          channel: stable
          cache: true

      - name: Install SwiftLint
        run: brew install swiftlint

      - name: Run SwiftLint
        run: swiftlint --config .swiftlint.yml --reporter github-actions-logging

      - name: Flutter pub get
        run: flutter pub get

      - name: Run iOS unit tests with coverage
        run: |
          cd ios
          xcodebuild test \
            -workspace Runner.xcworkspace \
            -scheme Runner \
            -destination 'platform=iOS Simulator,name=iPhone 16,OS=latest' \
            -enableCodeCoverage YES \
            -resultBundlePath TestResults.xcresult \
            ONLY_ACTIVE_ARCH=NO \
            CODE_SIGNING_ALLOWED=NO

      - name: Build iOS simulator debug
        run: flutter build ios --simulator --debug --no-codesign

      - name: Upload iOS build artifact
        uses: actions/upload-artifact@v4
        with:
          name: ios-simulator-build
          path: build/ios/iphonesimulator/
          retention-days: 7



