Object? _parseScalar(String v) {
  if (v == 'true') return true;
  if (v == 'false') return false;
  if (v == '[]') return <String>[];
  if (v == '{}') return <String, Object?>{};
  return v;
}

List<Map<String, Object>> _mergeReasonApis(List<List<Map<String, Object>>> lists) {
  final r = <Map<String, Object>>[];
  final seen = <String>{};
  for (final list in lists) {
    for (final api in list) {
      final name = api['api'] as String;
      if (seen.add(name)) {
        r.add(Map<String, Object>.from(api));
      } else {
        final ex = r.firstWhere((e) => e['api'] == name);
        (ex['reasons'] as List).addAll((api['reasons'] as List).where((rr) => !(ex['reasons'] as List).contains(rr)));
      }
    }
  }
  return r;
}

List<Map<String, Object>> _mergeCollectedData(List<List<Map<String, Object>>> lists) {
  final r = <Map<String, Object>>[];
  final seen = <String>{};
  for (final list in lists) {
    for (final d in list) {
      final t = d['type'] as String;
      if (seen.add(t)) r.add(Map<String, Object>.from(d));
    }
  }
  return r;
}

double _colorDelta(String h1, String h2) {
  int ph(String h) { final c = h.replaceFirst('#', ''); return int.parse(c, radix: 16); }
  final c1 = ph(h1); final c2 = ph(h2);
  final dr = ((c1 >> 16) & 0xFF) - ((c2 >> 16) & 0xFF);
  final dg = ((c1 >> 8) & 0xFF) - ((c2 >> 8) & 0xFF);
  final db = (c1 & 0xFF) - (c2 & 0xFF);
  return (dr * dr * 2 + dg * dg * 4 + db * db * 3).abs().toDouble();
}

class _FakeModule { final String id; final List<String> dependsOn; const _FakeModule(this.id, this.dependsOn); }

List<String> _resolveModules(List<String> roots, Map<String, _FakeModule> mods) {
  final r = <String>[]; final s = <String>{};
  void v(String id) { if (s.contains(id)) return; final m = mods[id]; if (m == null) throw StateError('Unknown: $id'); s.add(id); for (final d in m.dependsOn) v(d); r.add(id); }
  for (final root in roots) v(root);
  return r;
}



